import React, { useState, useEffect, useRef } from 'react';
import { Play, Terminal, Zap, CheckCircle, AlertTriangle, RefreshCcw, Server, Activity, ArrowRight, Wifi } from 'lucide-react';
import { Module } from '../types';

interface ModuleSimulatorProps {
  module: Module;
}

export const ModuleSimulator: React.FC<ModuleSimulatorProps> = ({ module }) => {
  const [isRunning, setIsRunning] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<any>(null);
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Simulation Parameters for MOD-01
  const [gridFreq, setGridFreq] = useState(50.00);
  const [capacity, setCapacity] = useState(3200); // MW

  const addLog = (message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const timestamp = new Date().toISOString().split('T')[1].slice(0, -1);
    setLogs(prev => [...prev, `[${timestamp}] ${type.toUpperCase()}: ${message}`]);
  };

  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const runVppSimulation = async () => {
    setIsRunning(true);
    setLogs([]);
    setProgress(0);
    setResult(null);

    // Step 1: Atlas Routing
    addLog('ATLAS: Received activation request for MOD-01', 'info');
    await new Promise(r => setTimeout(r, 600));
    addLog('ATLAS: Routing context to VOLTA Agent...', 'info');
    setProgress(10);

    // Step 2: Volta Initialization
    await new Promise(r => setTimeout(r, 800));
    addLog('VOLTA: Agent Active. Initializing VPP handshake...', 'success');
    addLog('VOLTA: Scanning 25 connected parks (RO)...', 'info');
    setProgress(30);

    // Step 3: Asset Aggregation
    await new Promise(r => setTimeout(r, 800));
    addLog(`VOLTA: Aggregated Capacity: ${capacity} MW`, 'info');
    addLog('VOLTA: Protocol: OpenADR 2.0b verified', 'success');
    setProgress(50);

    // Step 4: Grid Analysis
    await new Promise(r => setTimeout(r, 800));
    const currentFreq = 49.8 + Math.random() * 0.3;
    setGridFreq(currentFreq);

    if (currentFreq < 49.95) {
      addLog(`GRID_SENSOR: Frequency deviation detected (${currentFreq.toFixed(3)} Hz)`, 'warning');
      addLog('VOLTA: Calculating droop response...', 'info');
    } else {
      addLog(`GRID_SENSOR: Frequency nominal (${currentFreq.toFixed(3)} Hz)`, 'info');
    }
    setProgress(70);

    // Step 5: Dispatch
    await new Promise(r => setTimeout(r, 600));
    addLog('VOLTA: Dispatching active power setpoints to Huawei Inverters...', 'info');
    await new Promise(r => setTimeout(r, 400));

    // Result
    const responseTime = 0.092; // Fixed purely for the demo of the spec
    addLog(`VOLTA: Response confirmed. Latency: ${responseTime}s`, 'success');
    setProgress(100);

    setResult({
      status: 'OPTIMAL',
      injectedPower: currentFreq < 49.95 ? '450 MW' : '0 MW (Standby)',
      revenue: currentFreq < 49.95 ? '€12,500 (Spot)' : '€2,100 (Reservation)',
      latency: '92ms'
    });

    setIsRunning(false);
  };

  if (module.id !== 'm1') {
    return (
      <div className="p-8 text-center text-slate-500 border border-dashed border-slate-700 rounded-xl bg-slate-900/50">
        <Terminal className="w-12 h-12 mx-auto mb-4 opacity-50" />
        <p>Simulation sandbox not configured for this module yet.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-black/40 border border-slate-800 rounded-2xl p-6 shadow-inner">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h3 className="text-white font-bold flex items-center gap-2">
              <Activity className="w-5 h-5 text-amber-500" />
              VPP Simulation Arena
            </h3>
            <p className="text-xs text-slate-500 font-mono mt-1">VOLTA AGENT ENVIRONMENT</p>
          </div>
          {!isRunning && (
            <button 
              onClick={runVppSimulation}
              className="bg-amber-600 hover:bg-amber-500 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg shadow-amber-900/20"
            >
              <Play className="w-4 h-4" /> Initialize Test
            </button>
          )}
        </div>

        {/* Dashboard Simulation UI */}
        <div className="grid grid-cols-3 gap-4 mb-6">
          <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 flex flex-col items-center justify-center">
            <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Grid Freq</span>
            <span className={`text-2xl font-mono font-bold mt-1 ${isRunning ? 'animate-pulse' : ''} ${gridFreq < 49.9 ? 'text-red-400' : 'text-emerald-400'}`}>
              {gridFreq.toFixed(3)} Hz
            </span>
          </div>
          <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 flex flex-col items-center justify-center">
            <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Asset Pool</span>
            <div className="flex items-center gap-2 mt-1">
              <Server className="w-4 h-4 text-slate-400" />
              <span className="text-xl font-mono font-bold text-white">25</span>
            </div>
          </div>
          <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 flex flex-col items-center justify-center">
             <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Protocol</span>
             <div className="flex items-center gap-2 mt-1">
              <Wifi className="w-4 h-4 text-blue-400" />
              <span className="text-xs font-mono text-blue-300">OpenADR</span>
             </div>
          </div>
        </div>

        {/* Terminal Output */}
        <div className="bg-[#0c0c14] rounded-xl border border-slate-800 overflow-hidden">
          <div className="bg-slate-900/50 px-4 py-2 border-b border-slate-800 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Terminal className="w-3 h-3 text-slate-400" />
              <span className="text-[10px] text-slate-400 font-mono uppercase">System Logs</span>
            </div>
            <div className="flex gap-1.5">
               <div className={`w-2 h-2 rounded-full ${isRunning ? 'bg-amber-500 animate-pulse' : 'bg-slate-700'}`}></div>
            </div>
          </div>
          <div className="p-4 h-48 overflow-y-auto custom-scrollbar font-mono text-xs space-y-1.5">
            {logs.length === 0 && <span className="text-slate-600 italic">Ready to initialize simulation...</span>}
            {logs.map((log, i) => (
              <div key={i} className={`${
                log.includes('ERROR') ? 'text-red-400' : 
                log.includes('SUCCESS') ? 'text-emerald-400' : 
                log.includes('WARNING') ? 'text-amber-400' : 
                'text-slate-300'
              }`}>
                {log}
              </div>
            ))}
            <div ref={logsEndRef} />
          </div>
          {/* Progress Bar */}
          {isRunning && (
             <div className="h-1 bg-slate-800 w-full overflow-hidden">
                <div className="h-full bg-amber-500 transition-all duration-300" style={{ width: `${progress}%` }}></div>
             </div>
          )}
        </div>
      </div>

      {/* Results Card */}
      {result && (
        <div className="bg-emerald-900/10 border border-emerald-500/20 rounded-2xl p-6 animate-in slide-in-from-bottom-4">
          <div className="flex items-center gap-3 mb-4">
             <div className="bg-emerald-500/20 p-2 rounded-full">
               <CheckCircle className="w-6 h-6 text-emerald-500" />
             </div>
             <h4 className="text-lg font-bold text-white">Simulation Complete</h4>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
               <p className="text-[10px] text-emerald-500/70 uppercase font-bold">Status</p>
               <p className="text-sm font-bold text-white">{result.status}</p>
            </div>
            <div>
               <p className="text-[10px] text-emerald-500/70 uppercase font-bold">Power Injected</p>
               <p className="text-sm font-bold text-white">{result.injectedPower}</p>
            </div>
            <div>
               <p className="text-[10px] text-emerald-500/70 uppercase font-bold">Est. Revenue</p>
               <p className="text-sm font-bold text-white">{result.revenue}</p>
            </div>
            <div>
               <p className="text-[10px] text-emerald-500/70 uppercase font-bold">System Latency</p>
               <p className="text-sm font-bold text-white">{result.latency}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Module } from '../types';
import { X, ExternalLink, Copy, Terminal, PlayCircle, FileText } from 'lucide-react';
import { PlanetSoilingAnalysis } from './PlanetSoilingAnalysis';
