    <div className="fixed inset-0 z-50 flex justify-end">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="relative w-full max-w-3xl bg-slate-900 border-l border-slate-700 h-full overflow-y-auto shadow-2xl flex flex-col">

        {/* Header */}
        <div className="sticky top-0 bg-slate-900/95 backdrop-blur z-10 border-b border-slate-800 p-6 flex items-center justify-between shrink-0">
          <div>
            <span className="text-amber-500 font-mono text-sm mb-1 block">MODULE {module.number}</span>
            <h2 className="text-2xl font-bold text-white">{module.title}</h2>
          </div>
          <div className="flex items-center gap-4">
             {/* View Toggles */}
             <div className="bg-slate-800 p-1 rounded-lg flex border border-slate-700">
                <button 
                  onClick={() => setActiveView('overview')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${activeView === 'overview' ? 'bg-slate-700 text-white shadow' : 'text-slate-400 hover:text-slate-200'}`}
                >
                  <FileText className="w-3 h-3" /> Overview
                </button>
                <button 
                  onClick={() => setActiveView('test')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${activeView === 'test' ? 'bg-amber-600 text-white shadow' : 'text-slate-400 hover:text-slate-200'}`}
                >
                  <PlayCircle className="w-3 h-3" /> Test Module
                </button>
             </div>

             <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors">
               <X className="w-6 h-6" />
             </button>
          </div>
        </div>

        <div className="p-8 space-y-8 flex-1 overflow-y-auto custom-scrollbar">

          {activeView === 'test' ? (
             <ModuleSimulator module={module} />
          ) : (
            <>
              {/* SPECIAL INTEGRATION: MOD-04 Planet Labs */}
              {module.id === 'm4' && (
                <section className="mb-8 animate-in slide-in-from-right-4 duration-500">
                   <PlanetSoilingAnalysis />
                   <div className="my-8 border-t border-slate-800"></div>
                </section>
              )}

              {/* Overview */}
              <section className="animate-in fade-in duration-500">
                <h3 className="text-lg font-semibold text-white mb-3">Overview</h3>
                <p className="text-slate-300 leading-relaxed">{module.description}</p>
              </section>

              {/* Financial Impact */}
              <section className="bg-slate-800/50 rounded-xl p-5 border border-slate-700/50 animate-in fade-in duration-500 delay-100">
                <h3 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                  <span className="w-1 h-6 bg-emerald-500 rounded-full"></span>
                  Financial Impact
                </h3>
                <div className="grid grid-cols-2 gap-4">
                  {Object.entries(module.financialImpact).map(([key, value]) => (
                    <div key={key} className="bg-slate-900 rounded-lg p-3">
                      <span className="text-xs text-slate-500 uppercase font-bold tracking-wider">{key}</span>
                      <p className="text-emerald-400 font-mono font-medium mt-1">{value}</p>
                    </div>
                  ))}
                </div>
              </section>

              {/* API Integration */}
              <section className="animate-in fade-in duration-500 delay-200">
                <h3 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                  <span className="w-1 h-6 bg-blue-500 rounded-full"></span>
                  API Integrations
                </h3>
                <div className="space-y-6">
                  {module.apis.map((api, idx) => (
                    <div key={idx} className="border border-slate-700 rounded-xl overflow-hidden">
                      <div className="bg-slate-800/80 px-4 py-3 flex items-center justify-between border-b border-slate-700">
                        <div className="flex items-center gap-3">
                          <Terminal className="w-4 h-4 text-slate-400" />
                          <span className="font-semibold text-slate-200">{api.provider}</span>
                          {api.protocol && (
                            <span className="px-2 py-0.5 bg-slate-700 rounded text-xs text-slate-300">{api.protocol}</span>
                          )}
                        </div>
                        {api.docsUrl && (
                          <a href={api.docsUrl} target="_blank" rel="noreferrer" className="text-xs text-blue-400 hover:text-blue-300 flex items-center gap-1">
                            Docs <ExternalLink className="w-3 h-3" />
                          </a>
                        )}
                      </div>

                      <div className="p-4 bg-slate-900">
                        {api.description && (
                          <div className="mb-3 text-sm text-slate-400 italic border-l-2 border-slate-700 pl-3">
                            {api.description}
                          </div>
                        )}

                        {api.rateLimit && (
                          <div className="mb-3 text-xs text-amber-500/80 flex items-center gap-2">
                            <span className="px-1.5 py-0.5 border border-amber-500/30 rounded bg-amber-500/10">Rate Limit</span>
                            {api.rateLimit}
                          </div>
                        )}

                        {api.codeSnippet && (
                          <div className="relative group">
                            <pre className="bg-[#0d1117] p-4 rounded-lg overflow-x-auto custom-scrollbar text-sm font-mono text-slate-300 border border-slate-800">
                              <code>{api.codeSnippet}</code>
                            </pre>
                            <button className="absolute top-2 right-2 p-1.5 bg-slate-700/50 hover:bg-slate-700 rounded text-slate-400 hover:text-white opacity-0 group-hover:opacity-100 transition-opacity">
                              <Copy className="w-4 h-4" />
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </section>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Play, Terminal, Zap, CheckCircle, AlertTriangle, RefreshCcw, Server, Activity, ArrowRight, Wifi } from 'lucide-react';
import { Module } from '../types';

interface ModuleSimulatorProps {
  module: Module;
}

export const ModuleSimulator: React.FC<ModuleSimulatorProps> = ({ module }) => {
  const [isRunning, setIsRunning] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<any>(null);
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Simulation Parameters for MOD-01
  const [gridFreq, setGridFreq] = useState(50.00);
  const [capacity, setCapacity] = useState(3200); // MW

  const addLog = (message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const timestamp = new Date().toISOString().split('T')[1].slice(0, -1);
    setLogs(prev => [...prev, `[${timestamp}] ${type.toUpperCase()}: ${message}`]);
  };

  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const runVppSimulation = async () => {
    setIsRunning(true);
    setLogs([]);
    setProgress(0);
    setResult(null);

    // Step 1: Atlas Routing
    addLog('ATLAS: Received activation request for MOD-01', 'info');
    await new Promise(r => setTimeout(r, 600));
    addLog('ATLAS: Routing context to VOLTA Agent...', 'info');
    setProgress(10);

    // Step 2: Volta Initialization
    await new Promise(r => setTimeout(r, 800));
    addLog('VOLTA: Agent Active. Initializing VPP handshake...', 'success');
    addLog('VOLTA: Scanning 25 connected parks (RO)...', 'info');
    setProgress(30);

    // Step 3: Asset Aggregation
    await new Promise(r => setTimeout(r, 800));
    addLog(`VOLTA: Aggregated Capacity: ${capacity} MW`, 'info');
    addLog('VOLTA: Protocol: OpenADR 2.0b verified', 'success');
    setProgress(50);

    // Step 4: Grid Analysis
    await new Promise(r => setTimeout(r, 800));
    const currentFreq = 49.8 + Math.random() * 0.3;
    setGridFreq(currentFreq);

    if (currentFreq < 49.95) {
      addLog(`GRID_SENSOR: Frequency deviation detected (${currentFreq.toFixed(3)} Hz)`, 'warning');
      addLog('VOLTA: Calculating droop response...', 'info');
    } else {
      addLog(`GRID_SENSOR: Frequency nominal (${currentFreq.toFixed(3)} Hz)`, 'info');
    }
    setProgress(70);

    // Step 5: Dispatch
    await new Promise(r => setTimeout(r, 600));
    addLog('VOLTA: Dispatching active power setpoints to Huawei Inverters...', 'info');
    await new Promise(r => setTimeout(r, 400));

    // Result
    const responseTime = 0.092; // Fixed purely for the demo of the spec
    addLog(`VOLTA: Response confirmed. Latency: ${responseTime}s`, 'success');
    setProgress(100);

    setResult({
      status: 'OPTIMAL',
      injectedPower: currentFreq < 49.95 ? '450 MW' : '0 MW (Standby)',
      revenue: currentFreq < 49.95 ? '€12,500 (Spot)' : '€2,100 (Reservation)',
      latency: '92ms'
    });

    setIsRunning(false);
  };

  if (module.id !== 'm1') {
    return (
      <div className="p-8 text-center text-slate-500 border border-dashed border-slate-700 rounded-xl bg-slate-900/50">
        <Terminal className="w-12 h-12 mx-auto mb-4 opacity-50" />
