            <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Asset Pool</span>
            <div className="flex items-center gap-2 mt-1">
              <Server className="w-4 h-4 text-slate-400" />
              <span className="text-xl font-mono font-bold text-white">25</span>
            </div>
          </div>
          <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 flex flex-col items-center justify-center">
             <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Protocol</span>
             <div className="flex items-center gap-2 mt-1">
              <Wifi className="w-4 h-4 text-blue-400" />
              <span className="text-xs font-mono text-blue-300">OpenADR</span>
