  return (
    <div className="fixed inset-0 z-50 flex justify-end">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>
      <div className="relative w-full max-w-3xl bg-slate-900 border-l border-slate-700 h-full overflow-y-auto shadow-2xl flex flex-col">

