import React, { useState, useEffect, useRef } from 'react';
import { Play, Terminal, Zap, CheckCircle, AlertTriangle, RefreshCcw, Server, Activity, ArrowRight, Wifi, Shield, TrendingUp, History, Radio, Code, Lock } from 'lucide-react';
