import React, { useState, useEffect, useRef } from 'react';
import { Play, Terminal, Zap, CheckCircle, AlertTriangle, RefreshCcw, Server, Activity, ArrowRight, Wifi, Shield, TrendingUp, History, Radio, Code, Lock, MapPin, Scan, Flame, Crosshair } from 'lucide-react';
import { Module } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

interface ModuleSimulatorProps {
  module: Module;
}

interface TestResult {
