    const pMax = 15.5;
    const droop = 0.04;
    const fNom = 50.0;

    for (let i = 0; i < iterations; i++) {
        // Simulate frequency noise and events
        let currentFreq = 50.0;

        if (i > 10 && i < 20) currentFreq = 49.95; // Under-frequency event
        else if (i > 25 && i < 35) currentFreq = 50.08; // Over-frequency event
