                   <br/>Hash: 88a9...c2b1
                 </p>
              </div>
            </div>

            {/* Charts */}
            <div className="bg-slate-800/30 border border-slate-700 rounded-2xl p-6">
              <h4 className="text-sm font-bold text-white mb-6 uppercase tracking-widest">Metric Deviation Analysis</h4>
