                      {finalReport.results.map((entry: any, index: number) => (
                        <Cell key={`cell-${index}`} fill={entry.status === 'POSITIVE' ? '#10b981' : entry.status === 'CRITICAL' ? '#ef4444' : '#f59e0b'} />
                      ))}
