  Thermometer, Zap, Waves, BrainCircuit, ShieldCheck, Play, ArrowRight, RefreshCcw
} from 'lucide-react';

// --- TIS: TYPE DEFINITIONS (Based on JSON Specs) ---

interface TelemetryPoint {
  time: string;
  vibration: number; // g
  temp: number;      // C
  acoustic: number;  // kHz
}

interface PredictiveState {
  healthScore: number; // 0.0 - 1.0
  predictedMode: string;
  probFailure: number; // 0.0 - 1.0
  rulHours: number;
  status: 'NORMAL' | 'WARNING' | 'CRITICAL';
}

interface LogEntry {
  id: number;
  timestamp: string;
  type: 'INFO' | 'WARN' | 'CRITICAL' | 'SUCCESS';
  message: string;
  stage: string;
}

// --- ATLAS LOGIC ENGINE (Simulation) ---

class PredictionEngine {
  static generateTelemetry(tick: number, baselineTemp: number): TelemetryPoint {
    // Simulate sensor noise and drift
    const noise = (Math.random() - 0.5) * 0.1;
    const vibrationSpike = Math.random() > 0.95 ? 0.4 : 0; // Occasional jolt

    return {
      time: new Date().toLocaleTimeString().split(' ')[0],
      vibration: 0.3 + Math.sin(tick / 5) * 0.1 + noise + vibrationSpike,
      temp: baselineTemp + Math.log(tick + 1) * 2 + noise,
      acoustic: 450 + Math.cos(tick / 10) * 20 + noise * 100
    };
  }

  static analyzeBatch(buffer: TelemetryPoint[]): PredictiveState {
    const latest = buffer[buffer.length - 1];

    // Simple Heuristic Logic for Demo
    // 1. Feature Extraction (Simulated FFT by checking variance/peaks)
    const vibPeak = Math.max(...buffer.slice(-10).map(p => p.vibration));

    // 2. Inference Logic
    let health = 0.98;
    let prob = 0.02;
    let mode = "NOMINAL_OPERATION";
    let status: PredictiveState['status'] = 'NORMAL';

    if (vibPeak > 0.6) {
      health -= 0.15;
      prob += 0.30;
      mode = "BEARING_INNER_RACE_STRESS";
      status = 'WARNING';
    }
    if (latest.temp > 75) {
      health -= 0.30;
      prob += 0.50;
      mode = "THERMAL_RUNAWAY_RISK";
      status = 'CRITICAL';
    }

    // 3. RUL Estimation (Linear degradation sim)
    const degradationFactor = (1 - health) * 100;
    const rul = Math.max(0, 2000 - (degradationFactor * 50)); 

    return {
      healthScore: Number(health.toFixed(2)),
      predictedMode: mode,
      probFailure: Number(prob.toFixed(2)),
      rulHours: Math.floor(rul),
      status
    };
  }

  static validateSafety(state: PredictiveState): { approved: boolean; reason: string } {
    // Safety Protocol: Confidence Gating
    if (state.probFailure > 0.85) {
        return { approved: true, reason: "HIGH_CONFIDENCE_FAILURE_IMMINENT" };
    }
    if (state.probFailure > 0.50) {
        return { approved: false, reason: "FLAG_FOR_HUMAN_REVIEW (Confidence < 85%)" };
    }
    return { approved: false, reason: "NO_ACTION_REQUIRED" };
  }
}

export const PredictiveMaintenance: React.FC = () => {
  const [active, setActive] = useState(false);
  const [dataBuffer, setDataBuffer] = useState<TelemetryPoint[]>([]);
  const [prediction, setPrediction] = useState<PredictiveState>({
    healthScore: 1.0, predictedMode: "SYSTEM_IDLE", probFailure: 0.0, rulHours: 2000, status: 'NORMAL'
  });
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [tick, setTick] = useState(0);
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Simulation Loop
  useEffect(() => {
    let interval: any;
    if (active) {
      interval = setInterval(() => {
        setTick(t => t + 1);

        // 1. Ingest
        const newPoint = PredictionEngine.generateTelemetry(tick, 45); // 45C baseline
        setDataBuffer(prev => [...prev.slice(-49), newPoint]);

        // 2. Logic Flow Every 5 Ticks
        if (tick % 5 === 0) {
           runInferenceCycle([...dataBuffer, newPoint]);
        }

      }, 800); // 800ms tick
    }
    return () => clearInterval(interval);
  }, [active, tick, dataBuffer]);

  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const addLog = (type: LogEntry['type'], stage: string, message: string) => {
    setLogs(prev => [...prev, {
      id: Date.now(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      stage,
      message
    }]);
  };

  const runInferenceCycle = async (buffer: TelemetryPoint[]) => {
    addLog('INFO', 'INGEST', `Buffered ${buffer.length} telemetry frames via gRPC`);

    // Simulate Processing Delay
    await new Promise(r => setTimeout(r, 200));

    // 3. Inference
    const result = PredictionEngine.analyzeBatch(buffer);
    setPrediction(result);
    addLog('INFO', 'INFERENCE', `Model v2.4 output: Health ${result.healthScore}, Mode: ${result.predictedMode}`);

    // 4. Safety Handshake
    if (result.status !== 'NORMAL') {
        addLog('WARN', 'THRESHOLD', `Abnormal state detected! Prob: ${result.probFailure}`);

        const safetyCheck = PredictionEngine.validateSafety(result);
        if (safetyCheck.approved) {
