// Fetch Current Weather & OneCall
export const fetchLiveWeather = async (lat: number, lon: number) => {
  try {
    // Try OneCall 3.0 first as per prompt requirement
    const response = await fetch(`${ONE_CALL_URL}?lat=${lat}&lon=${lon}&appid=${API_KEY}&units=metric&exclude=minutely`);

    if (!response.ok) {
        throw new Error('OneCall API failed, falling back to 2.5');
    }
    const data = await response.json();
    return {
      current: data.current,
      hourly: data.hourly,
      daily: data.daily
    };
  } catch (e) {
    // Fallback to 2.5 weather if 3.0 fails (subscription issue)
    const response = await fetch(`${BASE_URL}/weather?lat=${lat}&lon=${lon}&appid=${API_KEY}&units=metric`);
    const data = await response.json();
    return {
      current: {
        ...data.main,
        ...data.wind,
        clouds: data.clouds.all,
        weather: data.weather,
        uvi: 0, // Not available in 2.5 standard
      },
      hourly: [],
      daily: []
    };
  }
};

// Fetch Air Pollution (Critical for MOD-04 Soiling & MOD-14 ESG)
export const fetchAirQuality = async (lat: number, lon: number): Promise<AirQuality> => {
  const response = await fetch(`${BASE_URL}/air_pollution?lat=${lat}&lon=${lon}&appid=${API_KEY}`);
  const data = await response.json();
  return data.list[0].components; // Returns CO, NO, NO2, O3, SO2, PM2_5, PM10, NH3
};

// Solar Irradiance Estimation (if API access restricted) or via OneCall
export const calculateSolarIrradiance = (cloudCover: number, uvi: number, hour: number): number => {
  // Simple heuristic model
  if (hour < 6 || hour > 20) return 0;
  const maxIrr = 1000; // W/m2
  const cloudFactor = 1 - (cloudCover / 100) * 0.75;
  const sunAngle = Math.sin(((hour - 6) / 14) * Math.PI);
  return Math.max(0, maxIrr * sunAngle * cloudFactor);
};

