import { X, ExternalLink, Copy, Terminal, PlayCircle, Sparkles, Wand2, RefreshCw, LayoutDashboard } from 'lucide-react';
import { analyzeModuleAction } from '../services/geminiService';

// Import Specific Module Implementations
import { ModuleSimulator } from './ModuleSimulator'; // Testing & Audit Engine
import { MOD06_Weather } from './modules/MOD06_Weather';
import { UniversalModule } from './modules/UniversalModule';
import { PerformanceBenchmarking } from './PerformanceBenchmarking'; // MOD-11
import { PredictiveMaintenance } from './PredictiveMaintenance'; // MOD-12

interface ModuleDetailProps {
  module: Module;
  onClose: () => void;
}

export const ModuleDetail: React.FC<ModuleDetailProps> = ({ module, onClose }) => {
  const [activeView, setActiveView] = useState<'overview' | 'test' | 'ai'>('test'); 
  const [aiGoal, setAiGoal] = useState('');
  const [aiResponse, setAiResponse] = useState<string | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const handleAiAnalysis = async () => {
    if (!aiGoal.trim()) return;
    setIsAiLoading(true);
    // User requested gemini-3-pro-preview with 32768 thinking budget
    const ai = new (await import('@google/genai')).GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Architectural directive for ${module.title}: ${aiGoal}`,
        config: { 
          thinkingConfig: { thinkingBudget: 32768 },
          systemInstruction: "You are SMART HELIOS PhD Architect. Provide deep technical blueprints, JSON schemas, and safety protocols for solar management modules."
        }
      });
      setAiResponse(response.text);
    } catch (e) {
      setAiResponse("Analysis module temporarily decoupled.");
    }
    setIsAiLoading(false);
  };

  const priorityColor = {
    [Priority.CRITICAL]: 'text-red-400 bg-red-400/10 border-red-400/20',
    [Priority.ESSENTIAL]: 'text-amber-400 bg-amber-400/10 border-amber-400/20',
    [Priority.ADVANCED]: 'text-blue-400 bg-blue-400/10 border-blue-400/20',
    [Priority.INNOVATIVE]: 'text-purple-400 bg-purple-400/10 border-purple-400/20',
    [Priority.FUTURE]: 'text-slate-400 bg-slate-400/10 border-slate-400/20',
  };

  // Router for Module Views
  const renderModuleContent = () => {
    switch (module.number) {
      // Use ModuleSimulator for core modules to enable Test Sequences & Audits
      case 1: // VPP Orchestrator
      case 2: // Frequency Regulation
      case 3: // Thermal Anomaly
      case 4: // Satellite Soiling
      case 5: // AI Anomaly Detection
        return <ModuleSimulator module={module} />;

      case 6: return <MOD06_Weather />;
      case 11: return <PerformanceBenchmarking />;
      case 12: return <PredictiveMaintenance />;
      default: return <UniversalModule module={module} />;
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex justify-end">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose}></div>
      <div className="relative w-full max-w-4xl bg-slate-950 border-l border-slate-800 h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">

        {/* Header Section */}
        <div className="flex-shrink-0 bg-slate-900/50 border-b border-slate-800">
          <div className="p-6 pb-4 flex items-start justify-between gap-4">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider border ${priorityColor[module.priority]}`}>
                  {module.priority}
                </span>
                <span className="text-slate-500 font-mono text-xs">MOD-{module.number.toString().padStart(2, '0')}</span>
              </div>
              <h2 className="text-2xl font-bold text-white leading-tight">{module.title}</h2>
            </div>
            <button onClick={onClose} className="p-2 -mr-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-xl transition-colors">
              <X className="w-6 h-6" />
            </button>
          </div>

          {/* Navigation Tabs */}
          <div className="px-6 flex gap-6 overflow-x-auto scrollbar-hide">
            <button 
              onClick={() => setActiveView('test')}
              className={`pb-3 text-sm font-bold border-b-2 transition-colors whitespace-nowrap flex items-center gap-2 ${
                activeView === 'test' ? 'text-white border-amber-500' : 'text-slate-500 border-transparent hover:text-slate-300'
              }`}
            >
              <PlayCircle className="w-4 h-4" /> Live Interface
            </button>
            <button 
              onClick={() => setActiveView('overview')}
              className={`pb-3 text-sm font-bold border-b-2 transition-colors whitespace-nowrap flex items-center gap-2 ${
                activeView === 'overview' ? 'text-white border-amber-500' : 'text-slate-500 border-transparent hover:text-slate-300'
              }`}
            >
              <LayoutDashboard className="w-4 h-4" /> Technical Specs
            </button>
            <button 
              onClick={() => setActiveView('ai')}
              className={`pb-3 text-sm font-bold border-b-2 transition-colors whitespace-nowrap flex items-center gap-2 ${
                activeView === 'ai' ? 'text-white border-amber-500' : 'text-slate-500 border-transparent hover:text-slate-300'
              }`}
            >
              <Sparkles className="w-4 h-4" /> AI Architect
            </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto custom-scrollbar bg-slate-950 p-6 md:p-8">
          {activeView === 'test' && renderModuleContent()}

          {activeView === 'ai' && (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="bg-indigo-950/10 border border-indigo-500/20 p-6 rounded-3xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-10">
                   <Sparkles className="w-32 h-32 text-indigo-500" />
                </div>
                <h3 className="text-white font-bold mb-4 flex items-center gap-2 uppercase tracking-widest text-xs relative z-10">
                  <Wand2 className="w-4 h-4 text-indigo-400" /> AI Recalibration Goal
                </h3>
                <div className="flex gap-2 relative z-10">
                  <input 
                    type="text" 
                    placeholder="e.g. Optimize for sub-90ms frequency response..."
                    className="flex-1 bg-slate-900/80 border border-slate-700 rounded-xl px-4 py-3 text-white focus:border-indigo-500 focus:outline-none text-sm"
                    value={aiGoal}
                    onChange={(e) => setAiGoal(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAiAnalysis()}
                  />
                  <button 
                    disabled={isAiLoading}
                    onClick={handleAiAnalysis}
                    className="bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-3 rounded-xl font-bold transition-all disabled:opacity-50"
                  >
                    {isAiLoading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              {aiResponse && (
                <div className="bg-slate-900/50 p-6 rounded-3xl border border-slate-800 space-y-4 animate-in fade-in zoom-in-95">
                  <div className="flex items-center justify-between border-b border-slate-800 pb-4">
                    <span className="text-[10px] font-mono text-indigo-400 uppercase tracking-widest flex items-center gap-2">
                      <Terminal className="w-3 h-3" /> Technical Directive
                    </span>
                  </div>
                  <div className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap font-mono">
                    {aiResponse}
                  </div>
                </div>
              )}
            </div>
          )}

          {activeView === 'overview' && (
            <div className="space-y-8">
              <section>
                <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest mb-3">Module Description</h3>
                <p className="text-slate-200 leading-relaxed text-lg font-light">{module.description}</p>
              </section>

              <section className="bg-slate-900/50 rounded-2xl p-6 border border-slate-800">
                <h3 className="text-sm font-bold text-slate-500 uppercase tracking-widest mb-4">Financial Impact</h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {Object.entries(module.financialImpact).map(([key, value]) => (
                    <div key={key} className="bg-slate-950 p-4 rounded-xl border border-slate-800/50">
                      <span className="text-[10px] text-slate-500 uppercase font-bold tracking-wider block mb-1">{key}</span>
                      <p className="text-emerald-400 font-mono text-lg font-medium">{value}</p>
                    </div>
                  ))}
                </div>
              </section>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Play, Terminal, Zap, CheckCircle, AlertTriangle, RefreshCcw, Server, Activity, ArrowRight, Wifi, Shield, TrendingUp, History, Radio, Code, Lock, MapPin, Scan, Flame, Crosshair, Satellite, Droplets, Coins, Layers, Brain, Search, Database } from 'lucide-react';
import { Module } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine, LineChart, Line, Legend } from 'recharts';

interface ModuleSimulatorProps {
  module: Module;
}

interface TestResult {
  suite: string;
  test: string;
  status: 'PASS' | 'FAIL';
  value?: string;
  latency?: string;
}

export const ModuleSimulator: React.FC<ModuleSimulatorProps> = ({ module }) => {
  const [isRunning, setIsRunning] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [results, setResults] = useState<TestResult[]>([]);
  const [progress, setProgress] = useState(0);
  const [activeSuite, setActiveSuite] = useState<string>('');

  // MOD-01 STATE
  const [gridFreq, setGridFreq] = useState(50.00);
  const [powerOutput, setPowerOutput] = useState(0.0);

  // MOD-02 SATU MARE SPECIFIC STATE
  const [satuMareState, setSatuMareState] = useState({
    freq: 50.00,
    power: 12.4, // Base load MW
    setpoint: 12.4,
    status: 'IDLE', // IDLE, HANDSHAKE, REGULATING, SAFETY_TRIP
    heartbeat: 0, // ms since last beat
    safetyLock: false
  });
  const [satuMareChart, setSatuMareChart] = useState<any[]>([]);

  // MOD-03 THERMAL STATE
  const [thermalMatrix, setThermalMatrix] = useState<number[]>(Array(64).fill(25)); // 8x8 grid, base 25C
  const [thermalStats, setThermalStats] = useState({ maxTemp: 25, anomalies: 0, scannedArea: 0 });

  // MOD-04 SOILING STATE
  const [soilingData, setSoilingData] = useState({
    opacity: 0,
    loss: 0,
    revenueLoss: 0,
    cleaningCost: 450, // EUR
    roiDays: 0
  });
  const [spectralChart, setSpectralChart] = useState<any[]>([]);

  // MOD-05 AI ANOMALY STATE
  const [aiAnomalyData, setAiAnomalyData] = useState({
    expected: 0,
    actual: 0,
    delta: 0,
    confidence: 0,
    status: 'CALIBRATING'
  });
  const [aiAnomalyChart, setAiAnomalyChart] = useState<any[]>([]);

  const logsEndRef = useRef<HTMLDivElement>(null);

  const addLog = (message: string, type: 'info' | 'success' | 'warning' | 'error' = 'info') => {
    const timestamp = new Date().toISOString().split('T')[1].slice(0, -1);
    setLogs(prev => [...prev, `[${timestamp}] ${type.toUpperCase()}: ${message}`]);
  };

  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  // --- MOD-01: VPP ORCHESTRATOR LOGIC ---
  const runMod01TestSequence = async () => {
    setIsRunning(true);
    setLogs([]);
    setResults([]);
    setProgress(0);
    setGridFreq(50.00);
    setPowerOutput(0.0);

    // --- SUITE 1: CORE VPP FUNCTIONALITY ---
    setActiveSuite('1. Core VPP Functionality');
    addLog('STARTING SUITE 1: CORE VPP FUNCTIONALITY', 'info');
    await new Promise(r => setTimeout(r, 600));

    setPowerOutput(12.5);
    addLog('TEST 1.1: Aggregating 5 solar plants (RO Portfolio)...', 'info');
    await new Promise(r => setTimeout(r, 400));
    setPowerOutput(65.2);
    addLog('VPP_ORCH: Handshake with RO-BUC-001, RO-BRA-001, RO-CLJ-001, RO-TIM-001, RO-CST-001 complete.', 'success');
    setResults(prev => [...prev, { suite: 'Core VPP', test: 'VPP Aggregation (5 plants)', status: 'PASS' }]);

    addLog('TEST 1.2: Plant Offline Handling (Simulating RO-CLJ-001 drop)...', 'info');
    await new Promise(r => setTimeout(r, 400));
    setPowerOutput(52.1);
    addLog('VPP_ORCH: Dynamic re-routing successful. Load balanced to 4 remaining assets.', 'success');
    setResults(prev => [...prev, { suite: 'Core VPP', test: 'Plant Offline Handling', status: 'PASS' }]);
    setProgress(20);

    // --- SUITE 2: RESPONSE TIME (CRITICAL) ---
    setActiveSuite('2. Response Time (92ms Requirement)');
    addLog('STARTING SUITE 2: RESPONSE TIME (STRICT 92ms)', 'info');
    await new Promise(r => setTimeout(r, 800));

    const latency = (Math.random() * 5 + 87.2).toFixed(1);
    addLog(`TEST 2.1: Dispatch latency check. Measured: ${latency}ms`, 'success');
    setResults(prev => [...prev, { suite: 'Response Time', test: '92ms Requirement', status: 'PASS', latency: `${latency}ms` }]);

    addLog('TEST 2.2: Load test (100 concurrent grid events)...', 'info');
    await new Promise(r => setTimeout(r, 600));
    addLog('SYSTEM: P95 latency stable at 78.2ms under saturation.', 'success');
    setResults(prev => [...prev, { suite: 'Response Time', test: 'Load Test (100 concurrent)', status: 'PASS' }]);
    setProgress(40);

    // --- SUITE 3: GRID-FORMING CAPABILITY ---
    setActiveSuite('3. Grid-Forming Capability');
    addLog('STARTING SUITE 3: GRID-FORMING CONTROL', 'info');

    // Simulate frequency swing
    setGridFreq(49.75);
    addLog('GRID_SENSE: Frequency deviation detected (49.75 Hz)', 'warning');
    addLog('VOLTA_PPC: Droop control active. Injecting active power...', 'info');
    setPowerOutput(58.5); // Injecting
    await new Promise(r => setTimeout(r, 400));
    setGridFreq(49.98);
    addLog('GRID_SENSE: Frequency stabilized at 49.98 Hz', 'success');

    setResults(prev => [...prev, { suite: 'Grid-Forming', test: 'Frequency Control', status: 'PASS' }]);
    setResults(prev => [...prev, { suite: 'Grid-Forming', test: 'Synthetic Inertia', status: 'PASS' }]);
    setProgress(60);

    // --- SUITE 4: BLACK START CAPABILITY ---
    setActiveSuite('4. Black Start Capability');
    addLog('STARTING SUITE 4: BLACK START (FROM ZERO)', 'info');
    addLog('GRID_STATE: Status: BLACKOUT', 'error');
    setPowerOutput(0);
    setGridFreq(0);
    await new Promise(r => setTimeout(r, 800));
    addLog('VOLTA_PPC: Initiating sub-network energization sequence...', 'info');
    setGridFreq(10);
    await new Promise(r => setTimeout(r, 600));
    setGridFreq(50.00);
    setPowerOutput(5.2);
    addLog('SUCCESS: Essential services energized (RO-BUC-001 back-fed)', 'success');
    setResults(prev => [...prev, { suite: 'Black Start', test: 'Black Start Sequence', status: 'PASS', value: '243s' }]);
    setProgress(75);

    // --- SUITE 5: API INTEGRATIONS ---
    setActiveSuite('5. API Integrations');
    addLog('STARTING SUITE 5: API HANDSHAKES', 'info');
    addLog('AUTH: Authenticating with Huawei FusionSolar Northbound...', 'info');
    await new Promise(r => setTimeout(r, 400));
    addLog('API: XSRF-TOKEN verified. Session Active.', 'success');
    setResults(prev => [...prev, { suite: 'API', test: 'Huawei FusionSolar', status: 'PASS' }]);

    addLog('PROTOCOL: Registering VEN on OpenADR 2.0b...', 'info');
    await new Promise(r => setTimeout(r, 400));
    addLog('API: VEN_ID [VPP-RO-001] registered with VTN.', 'success');
    setResults(prev => [...prev, { suite: 'API', test: 'OpenADR 2.0b', status: 'PASS' }]);
    setProgress(90);

    // --- SUITE 6: ECONOMIC VALIDATION ---
    setActiveSuite('6. Economic Validation');
    addLog('STARTING SUITE 6: NPV & ROI ANALYSIS', 'info');
    await new Promise(r => setTimeout(r, 800));
    addLog('FIN_OPS: Projecting 10-year cash flow with PTJ Grant integration...', 'info');
    addLog('FIN_OPS: NPV Confirmed: €46.8M (Tolerance ±10%)', 'success');
    setResults(prev => [...prev, { suite: 'Economics', test: 'NPV Calculation (€47M)', status: 'PASS', value: '€46.8M' }]);
    setResults(prev => [...prev, { suite: 'Economics', test: 'Cost Savings (40-60%)', status: 'PASS', value: '52.3%' }]);
    setPowerOutput(65.2); // Restore power

    setProgress(100);
    addLog('ALL TEST SUITES COMPLETED SUCCESSFULLY.', 'success');
    setIsRunning(false);
  };

  // --- MOD-02: SATU MARE IMPLEMENTATION LOGIC ---
  const runSatuMareSequence = async () => {
    setIsRunning(true);
    setLogs([]);
    setResults([]);
    setProgress(0);
    setSatuMareChart([]);
    setSatuMareState(prev => ({...prev, status: 'HANDSHAKE', freq: 50.00, power: 12.4}));

    // 1. ASSET TWIN CONFIG
    setActiveSuite('1. Asset Digital Twin Configuration');
    addLog('ATLAS: Loading configuration for PV_SATU_MARE_01...', 'info');
    await new Promise(r => setTimeout(r, 800));
    addLog('TWIN: Location 47.7900N, 22.8800E verified.', 'success');
    addLog('TWIN: Capacity 15.5 MW | Connection 110kV confirmed.', 'success');
    setResults(prev => [...prev, { suite: 'Asset Config', test: 'Digital Twin Init', status: 'PASS', value: 'PV_SATU_MARE_01' }]);
    setProgress(10);

    // 2. GRID MONITOR (MQTT) HANDSHAKE
    setActiveSuite('2. Grid Monitor Integration (MQTT)');
    addLog('ATLAS: Connecting to Grid Monitor via MQTT (broker.grid-monitor.ro)...', 'info');
    await new Promise(r => setTimeout(r, 500));
    addLog('MQTT: Topic [grid/ro/satu_mare/freq] subscribed.', 'success');
    addLog('MQTT: Data Stream Active (50Hz telemetry @ 10ms).', 'success');
    setResults(prev => [...prev, { suite: 'Connectivity', test: 'Grid Monitor (MQTT)', status: 'PASS', latency: '9ms' }]);
    setProgress(20);

    // 3. API HANDSHAKE
    setActiveSuite('3. Control API Handshake (IEC-60870-5-104)');
    addLog('ATLAS: Initiating secure handshake with SM_RTU_01...', 'info');
    await new Promise(r => setTimeout(r, 500));
    addLog('NET: POST /api/v1/fr-as/handshake -> 200 OK', 'success');
    addLog('NET: Latency check: 12ms (Excellent)', 'success');
    setSatuMareState(prev => ({...prev, status: 'REGULATING'}));
    setResults(prev => [...prev, { suite: 'Connectivity', test: 'API Handshake (IEC-104)', status: 'PASS', latency: '12ms' }]);
    setProgress(30);

    // 4. LIVE REGULATION SIMULATION LOOP
    setActiveSuite('4. Live Frequency Regulation (Droop 4%)');
    addLog('CTRL: Enabling autonomous Droop Control loop...', 'info');

    const iterations = 40;
    const baseLoad = 12.4;
    const pMax = 15.5;
    const droop = 0.04;
    const fNom = 50.0;

    for (let i = 0; i < iterations; i++) {
        // Simulate frequency noise and events
        let currentFreq = 50.0;

        if (i > 10 && i < 20) currentFreq = 49.95; // Under-frequency event
        else if (i > 25 && i < 35) currentFreq = 50.08; // Over-frequency event
        else currentFreq = 50.0 + (Math.random() - 0.5) * 0.02; // Noise

        // IMPLEMENTING THE PYTHON LOGIC FROM PROMPT
        const deadband = 0.02;
        const deltaF = currentFreq - fNom;
        let pAdjust = 0;

        if (Math.abs(deltaF) >= deadband) {
             const deltaP = - (deltaF / fNom) * (1 / droop) * pMax;
             pAdjust = deltaP;
        }

        const newPower = Math.max(0, Math.min(pMax, baseLoad + pAdjust));

        // Heartbeat simulation
        const heartbeat = Math.random() * 500 + 50; // Random heartbeat latency

        setSatuMareState(prev => ({
            ...prev, 
            freq: currentFreq, 
            power: newPower, 
            heartbeat: heartbeat,
            safetyLock: heartbeat > 5000 // Trigger safety if > 5s
        }));

        setSatuMareChart(prev => [...prev, { 
            time: i, 
            freq: currentFreq, 
            power: newPower, 
            limit: pMax 
        }].slice(-30));

        if (i === 11) addLog('GRID: Freq drop detected (49.95Hz). Injecting power...', 'warning');
        if (i === 15) addLog(`CTRL: Regulation Active. +${(newPower - baseLoad).toFixed(2)} MW`, 'success');
        if (i === 26) addLog('GRID: Over-freq (50.08Hz). Curtailing power...', 'warning');

        await new Promise(r => setTimeout(r, 250)); // Fast loop
        setProgress(30 + (i/iterations)*40);
    }

    setResults(prev => [...prev, { suite: 'FR-AS Logic', test: 'Droop Response', status: 'PASS', value: '4% Slope' }]);
    setResults(prev => [...prev, { suite: 'Safety', test: 'Heartbeat Watchdog', status: 'PASS', value: 'Active' }]);
    setProgress(70);

    // 5. ECONOMIC VALIDATION
    setActiveSuite('5. Financial Impact Analysis');
    addLog('FIN: Aggregating Ancillary Service credits...', 'info');
    await new Promise(r => setTimeout(r, 600));
    addLog('FIN: Validating against $18.26B Ancillary Market Model...', 'info');
    addLog('FIN: Projected Annual Revenue: $10.2M (Exceeds $10M target)', 'success');
    addLog('FIN: NPV Calculation: €52.1M (Exceeds €52M target)', 'success');
    setResults(prev => [...prev, { suite: 'Economics', test: 'Revenue Target ($10M)', status: 'PASS', value: '$10.2M' }]);
    setResults(prev => [...prev, { suite: 'Economics', test: 'NPV Target (€52M)', status: 'PASS', value: '€52.1M' }]);
    setProgress(100);

    addLog('ATLAS: Simulation complete. Asset returned to baseline.', 'success');
    setIsRunning(false);
    setSatuMareState(prev => ({...prev, status: 'IDLE', freq: 50.00, power: 12.4}));
  };

  // --- MOD-03: THERMAL ANOMALY DETECTION (SATU MARE) ---
  const runThermalScanSequence = async () => {
    setIsRunning(true);
    setLogs([]);
    setResults([]);
    // Reset Grid
    setThermalMatrix(Array(64).fill(22)); // Ambient 22C
    setThermalStats({ maxTemp: 22, anomalies: 0, scannedArea: 0 });

    // 1. GEO FENCING CONFIG
    setActiveSuite('1. Geo-Fencing & Target Config');
    addLog('ATLAS: Initializing TAD-V4 for Target SM-PARK-001...', 'info');
    await new Promise(r => setTimeout(r, 600));
    addLog('GEO: Loading Polygon [22.8725, 47.7920] (Parcul Central)...', 'info');
    addLog('GEO: Buffer zone 50m applied. Resolution 10px.', 'success');
    setResults(prev => [...prev, { suite: 'Configuration', test: 'AOI Lock (Satu Mare)', status: 'PASS', value: 'SM-PARK-001' }]);

    // 2. INGESTION STREAM
    setActiveSuite('2. Data Ingestion Pipeline');
    addLog('NET: Handshake with Sentinel-2 L2A Hub...', 'info');
    await new Promise(r => setTimeout(r, 500));
    addLog('NET: Drone feed detected (RTSP). Switching to Hybrid Source.', 'warning');
    addLog('DATA: Radiometric Calibration (Emissivity 0.98)...', 'success');
    setResults(prev => [...prev, { suite: 'Ingestion', test: 'Hybrid Stream (Sat+Drone)', status: 'PASS', latency: '450ms' }]);

    // 3. SCANNING & ANALYSIS LOOP
    setActiveSuite('3. Z-Score Spatial Analysis');
    addLog('CORE: Executing Segmentation logic (NDVI masking)...', 'info');

    // Simulate the scan
    for (let i = 0; i < 64; i++) {
        // Create heat pattern
        setThermalMatrix(prev => {
            const next = [...prev];
            // Base noise
            next[i] = 25 + Math.random() * 5; 

            // Introduce anomalies at specific indices
            if (i === 18) next[i] = 48; // Warning
            if (i === 42) next[i] = 72; // CRITICAL FIRE
            if (i === 43) next[i] = 68; // Spread

            return next;
        });

        // Update stats
        setThermalStats(prev => {
            const currentTemp = thermalMatrix[i] || 25;
            return {
