        setThermalStats(prev => {
            const currentTemp = thermalMatrix[i] || 25;
            return {
                maxTemp: Math.max(prev.maxTemp, currentTemp),
                anomalies: currentTemp > 45 ? prev.anomalies + 1 : prev.anomalies,
                scannedArea: Math.round(((i + 1) / 64) * 100)
